import Foundation

/// Where content comes from. `.api` talks to the backend; `.bundled` reads the
/// fixtures generated by `npm run fixtures` in backend/, for previews, tests and
/// running the app before the API is deployed.
struct ContentSource: Sendable {
    var today: @Sendable (_ language: String) async throws -> Piece
    /// Pieces published on or before `day` (YYYY-MM-DD), each with its `publishDate`.
    var pieces: @Sendable (_ language: String, _ day: String) async throws -> [PieceSummary]
    /// Scheduled days up to and including `day`, oldest first.
    var schedule: @Sendable (_ language: String, _ day: String) async throws -> [ScheduledDay]
    var piece: @Sendable (_ id: String, _ language: String) async throws -> Piece
    var glossary: @Sendable (_ language: String) async throws -> [GlossaryTerm]
    var composers: @Sendable (_ language: String) async throws -> [Composer]

    static let api = ContentSource(
        today: { try await APIClient.shared.today(language: $0).piece },
        pieces: { language, day in
            let published = try await APIClient.shared.pieces(day: day, language: language)
            // Settings › Test › whole catalogue: the API lists published pieces only, so the
            // unscheduled ones come from the bundled fixtures (without a publish date).
            guard ContentSource.showsWholeCatalogue,
                  let bundled = try? Fixtures.load([PieceSummary].self, "pieces", language) else { return published }
            let known = Set(published.map(\.id))
            return published + bundled.filter { !known.contains($0.id) }.map { var p = $0; p.publishDate = nil; return p }
        },
        schedule: { try await APIClient.shared.schedule(until: $1, language: $0) },
        piece: { id, language in
            do { return try await APIClient.shared.piece(id: id, language: language) } catch {
                // An unpublished piece shown by the whole-catalogue test setting.
                if ContentSource.showsWholeCatalogue, let p = try? Fixtures.load(Piece.self, "piece-\(id)", language) { return p }
                throw error
            }
        },
        glossary: { try await APIClient.shared.glossary(language: $0) },
        composers: { try await APIClient.shared.composers(language: $0) }
    )

    static let bundled = ContentSource(
        today: { language in
            // Same plan as the API's daily_schedule (content/schedule.yaml).
            let schedule = try Fixtures.load(Fixtures.Schedule.self, "schedule", language)
            let id = schedule.days[APIClient.day()] ?? schedule.order[0]
            return try Fixtures.load(Piece.self, "piece-\(id)", language)
        },
        pieces: { language, day in
            // Publish date = each piece's latest scheduled day up to `day`, as the API computes it.
            let schedule = try Fixtures.load(Fixtures.Schedule.self, "schedule", language)
            var dates: [String: String] = [:]
            for (date, id) in schedule.days where date <= day && date > (dates[id] ?? "") { dates[id] = date }
            let all = ContentSource.showsWholeCatalogue
            return try Fixtures.load([PieceSummary].self, "pieces", language).compactMap { piece in
                guard let date = dates[piece.id] else { return all ? piece : nil }
                var piece = piece
                piece.publishDate = date
                return piece
            }
        },
        schedule: { language, day in
            let schedule = try Fixtures.load(Fixtures.Schedule.self, "schedule", language)
            return schedule.days.filter { $0.key <= day }
                .map { ScheduledDay(day: $0.key, pieceId: $0.value) }
                .sorted { $0.day < $1.day }
        },
        piece: { try Fixtures.load(Piece.self, "piece-\($0)", $1) },
        glossary: { try Fixtures.load([GlossaryTerm].self, "glossary", $0) },
        composers: { try Fixtures.load([Composer].self, "composers", $0) }
    )

    static var `default`: ContentSource { isAPI ? .api : .bundled }

    /// Settings › Test: the Library and Keşfet list unscheduled pieces too (from the bundled
    /// fixtures when reading the API), so new pieces can be read on a device before they are
    /// scheduled. Never in App Store builds.
    nonisolated static var showsWholeCatalogue: Bool {
        TestBuild.isActive && UserDefaults.standard.bool(forKey: "debugShowAllPieces")
    }

    /// Release builds read the API; debug builds use bundled fixtures unless DC_USE_API=1.
    static var isAPI: Bool {
        #if DEBUG
        ProcessInfo.processInfo.environment["DC_USE_API"] == "1"
        #else
        true
        #endif
    }
}

/// One day of the published plan: Today pages back through these.
nonisolated struct ScheduledDay: Codable, Hashable, Sendable {
    /// "YYYY-MM-DD" in the reader's calendar.
    let day: String
    let pieceId: String
}

nonisolated enum Fixtures {
    struct Schedule: Decodable { let start: String; let order: [String]; let days: [String: String] }

    static func load<T: Decodable>(_ type: T.Type, _ name: String, _ language: String) throws -> T {
        guard let url = Bundle.main.url(forResource: name, withExtension: "json", subdirectory: "Fixtures/\(language)")
            ?? Bundle.main.url(forResource: name, withExtension: "json", subdirectory: "Fixtures/en")
        else { throw APIError.notFound }
        return try APIClient.decode(T.self, from: Data(contentsOf: url))
    }
}
